import { createGateway } from './slack.js';

export class Chat extends Agent {
  async onMessage(connection, message) {
    connection.send(`echo: ${message}`);
  }

  // Inbound Slack events, delivered over RPC by the channel gateway.
  async receive(event, origin) {
    if (event.type !== 'message') return;

    // Slack redelivers events it thinks were not acknowledged in time; the
    // gateway's event id is stable across redeliveries, so reply only once.
    this.sql`CREATE TABLE IF NOT EXISTS slack_events (id TEXT PRIMARY KEY)`;
    if (this.sql`SELECT id FROM slack_events WHERE id = ${event.eventId}`.length) return;
    this.sql`INSERT INTO slack_events (id) VALUES (${event.eventId})`;

    const text = event.message.parts
      .filter((part) => part.type === 'text')
      .map((part) => part.text)
      .join('');
    await createGateway(this.env).deliver(origin.surface, { markdown: `echo: ${text}` });
  }
}

export default {
  async fetch(request, env) {
    return (
      (await createGateway(env).fetch(request)) ??
      (await routeAgentRequest(request, env)) ??
      new Response('Not found', { status: 404 })
    );
  },
};

