import { getAgentByName } from 'agents';
import { ChannelGateway } from 'agents/experimental/channels';
import { slack } from 'agents/experimental/channels/slack';

const SLACK_API = 'https://slack.com/api';

// The Slack channel in agents 0.27.0 verifies and normalizes inbound events but
// does not implement outbound delivery yet, so replies are posted here with
// chat.postMessage. Drop this once the package's channel provides `deliver`.
function slackDeliver(botToken) {
  return async (surface, message) => {
    const { address } = surface;
    const channel = address.channelId ?? address.userId;
    const text = message.title ? `*${message.title}*\n${message.markdown}` : message.markdown;

    let response;
    try {
      response = await fetch(`${SLACK_API}/chat.postMessage`, {
        method: 'POST',
        headers: {
          authorization: `Bearer ${botToken}`,
          'content-type': 'application/json; charset=utf-8',
        },
        body: JSON.stringify({ channel, text, ...(address.threadTs && { thread_ts: address.threadTs }) }),
      });
    } catch (error) {
      return { status: 'uncertain', error: { code: 'SLACK_NETWORK_ERROR', message: String(error) } };
    }

    const body = await response.json().catch(() => null);
    if (body?.ok) return { status: 'delivered', reference: `${body.channel}:${body.ts}` };
    return {
      status: 'failed',
      retryable: response.status === 429 || response.status >= 500,
      error: { code: 'SLACK_API_ERROR', message: body?.error ?? `HTTP ${response.status}` },
    };
  };
}

export function createGateway(env) {
  const channel = slack({
    botToken: env.SLACK_BOT_TOKEN,
    webhook: { signingSecret: env.SLACK_SIGNING_SECRET, path: '/webhooks/slack' },
    // Each Slack user (scoped to their workspace) is their own participant and,
    // by default, gets a Chat instance of their own.
    participant: (event) => (event.actor ? { id: event.actor.id, name: event.actor.username } : null),
  });
  channel.deliver ??= slackDeliver(env.SLACK_BOT_TOKEN);

  return new ChannelGateway({
    channels: { slack: channel },
    agent(route) {
      const stub = () => getAgentByName(env.Chat, route);
      return {
        receive: async (event, origin) => (await stub()).receive(event, origin),
        fetch: async (request) => (await stub()).fetch(request),
      };
    },
  });
}

